import { test } from "@playwright/test";

const EMAIL = process.env.E2E_EMAIL!;
const PASSWORD = process.env.E2E_PASSWORD!;

test("inspect stripe card fields", async ({ page }) => {
  test.setTimeout(180_000);

  await page.goto("/sign-in");
  await page.locator('input[name="email"]').fill(EMAIL);
  await page.locator('input[name="password"]').fill(PASSWORD);
  await page.getByRole("button", { name: /sign in/i }).click();
  await page.waitForURL(/\/account/);

  await page.goto("/join/checkout?tier=supporter&cadence=monthly");
  await page.waitForURL(/checkout\.stripe\.com/, { timeout: 60_000 });

  await page
    .locator("#payment-method-accordion-item-title-card")
    .check({ force: true });
  await page.waitForTimeout(8000);
  await page.screenshot({
    path: "artifacts/probe-after-card-select.png",
    fullPage: true,
  });

  console.log("=== FRAMES ===");
  for (const frame of page.frames()) {
    console.log(
      `FRAME name="${frame.name()}" url=${frame.url().slice(0, 100)}`,
    );
  }

  console.log("=== IFRAME ELEMENTS ===");
  const iframeAttrs = await page.evaluate(() =>
    Array.from(document.querySelectorAll("iframe")).map((f) => ({
      name: f.getAttribute("name"),
      title: f.getAttribute("title"),
      src: (f.getAttribute("src") || "").slice(0, 80),
    })),
  );
  console.log(JSON.stringify(iframeAttrs, null, 1));

  console.log("=== CANDIDATE CARD INPUTS PER FRAME ===");
  for (const frame of page.frames()) {
    for (const sel of [
      'input[name="number"]',
      "#cardNumber",
      'input[autocomplete="cc-number"]',
    ]) {
      const n = await frame
        .locator(sel)
        .count()
        .catch(() => 0);
      if (n)
        console.log(
          `HIT ${sel} in frame "${frame.name()}" (${frame.url().slice(0, 60)})`,
        );
    }
  }
});
